let gallerySnapshot=null;
function renderGallery(){const keep=modalKind==='gallery'&&gallerySnapshot?.tier===galleryTier,dialog=$('modal'),content=$('modal-content'),active=document.activeElement,focus=active?.dataset?.galleryTier;const anchor=keep?[...content.querySelectorAll('[data-gallery-hero]')].find(el=>el.getBoundingClientRect().bottom>dialog.getBoundingClientRect().top+20):null;const saved=keep?{top:dialog.scrollTop,inner:content.scrollTop,id:anchor?.dataset.galleryHero,y:anchor?.getBoundingClientRect().top,focus}:null;openModal(galleryWorldHTML(world,uid,galleryTier,currentTime()),'gallery');gallerySnapshot={tier:galleryTier};if(saved){dialog.scrollTop=saved.top;content.scrollTop=saved.inner;const el=content.querySelector('[data-gallery-hero="'+saved.id+'"]');if(el)dialog.scrollTop+=el.getBoundingClientRect().top-saved.y;if(saved.focus!==undefined)content.querySelector('[data-gallery-tier="'+saved.focus+'"]')?.focus({preventScroll:true});}else dialog.scrollTop=0;}
function showOfficer(id){officerDetail={id,target:'',gallery:modalKind==='gallery'?{top:$('modal').scrollTop,tier:galleryTier}:null};renderOfficerDetail();}
function renderOfficerDetail(){if(!officerDetail)return;const scroll=$('modal-content').scrollTop;openModal((officerDetail.gallery?'<button data-gallery-back class="gallery-back">← 무장 도감으로 돌아가기</button>':'')+officerDetailHTML(world,uid,officerDetail.id,currentTime(),officerDetail.target,busy),'officer');$('modal-content').scrollTop=scroll;}
function locateOfficer(id){sideTab='command';startSelection(id);lastSideSignature='';map.focusTerritory?.(id);render();}
async function confirmOfficerMove(){if(!officerDetail||busy)return;const row=officerRows(world,uid).find(r=>r.u.id===officerDetail.id),to=officerDetail.target;if(!row?.t||!to)return;const from=row.t.id,id=row.u.id;await submit({type:'move',from,to,unitIds:[id],moveHeroId:effectOf(row.u)?.movement?id:'',seed:entropy(),expectedTerritories:{[from]:world.territories[from].revision,[to]:world.territories[to].revision}});if(world.territories[to].units.some(u=>u.id===id)){closeModal();sideTab='heroes';lastInfoSignature='';render();}}

function fieldScope(){
  if(!uid||!store||store.uid&&store.uid!==uid)return null;
  const key=`samguk-field:${store.mode}:${store.config?.worldId||'practice'}:${uid}`;
  if(fieldMemory?.key!==key){fieldMemory=new FieldMemory(localStorage,key);fieldMemory.initializeNews(world);cityFilter=fieldMemory.get('cities',{query:'',filter:'all',sort:'name'});newsFilter=fieldMemory.get('newsFilter',{scope:'mine',kind:'all'});chatFilter=fieldMemory.get('chatFilter','all');chatSeen=new Set(fieldMemory.get('chatSeen',[]));if(!fieldMemory.get('chatInitialized',false)&&chat){chatSeen=new Set(publicChat(chatMessages(chat)).map(m=>String(m.seq)));fieldMemory.set('chatSeen',[...chatSeen]);fieldMemory.set('chatInitialized',true);}const draft=fieldMemory.get('draft','');if($('chat-input')&&!$('chat-input').value)$('chat-input').value=draft;lastChatSignature='';}
  return fieldMemory;
}
function clearTerritory(){if(busy||myPendingBattle(world,uid))return;source=null;target=null;selected.clear();battleChoice={key:'',ids:[]};chance={key:'',value:null};lastSideSignature='';render();}
function fieldPanels(){
  const mem=fieldScope(),rows=mem?.unseen(world,uid)||[];const box=$('return-news');box.hidden=!rows.length||!uid;
  if(rows.length)box.innerHTML=`<button data-open-my-news>이 기기에서 마지막 확인 이후 · 내 소식 ${rows.length}건</button><small>보관된 최근 100개 기록 기준${Math.min(...Object.values(world.history).map(e=>e.at))>mem.get('news',{at:Infinity}).at?' · 일부 이전 소식은 보관 범위 밖입니다.':''}</small>`;
  $('jump-orders').textContent='명령 · '+(placeInfo(source)?.ko||'내 도시');
  if(lastLegend!==JSON.stringify(Object.values(view.players).map(p=>[p.uid,p.name,p.color]))){lastLegend=JSON.stringify(Object.values(view.players).map(p=>[p.uid,p.name,p.color]));$('ruler-legend').innerHTML=`<button data-highlight="">전체</button>`+Object.values(view.players).map(p=>`<button data-highlight="${esc(p.uid)}"><i style="background:${COLORS[p.color%COLORS.length]}"></i>${esc(p.name)}</button>`).join('');}
  document.body.classList.toggle('has-modal',$('modal').open);
}
function openMyNews(){sideTab='history';newsFilter.scope='mine';lastInfoSignature='';render();}
function readVisibleNews(){if(document.hidden)return;const es=[...document.querySelectorAll('[data-news-id]')].filter(el=>{const r=el.getBoundingClientRect(),host=el.closest('.command-scroll,.modal-inner')?.getBoundingClientRect();return r.width&&r.height&&r.bottom>Math.max(0,host?.top||0)&&r.top<Math.min(innerHeight,host?.bottom||innerHeight);}).map(el=>world.history[el.dataset.newsId]).filter(Boolean);if(es.length)fieldMemory?.readNews(world,es);}
function readNews(){fieldScope()?.readNews(world,historyRows(world,uid,newsFilter));$('return-news').hidden=true;}
async function replayBattle(id){if(myPendingBattle(world,uid)){toast('관평의 구조 선택을 먼저 마쳐 주세요.');return;}const season=store?.config?.worldId;try{let e=world.history[id];if(!e?.result&&store?.battleDetail){toast('이 전투의 상세 기록을 불러옵니다.');e=await store.battleDetail(id);}if(season!==store?.config?.worldId||myPendingBattle(world,uid))return;if(!e?.result){toast('상세 기록이 없습니다.');return;}showBattle(battleRecord(e.result),{replay:true,at:e.at,text:e.text});}catch(error){toast(error.message||'전투 기록을 불러오지 못했습니다.');}}
function battleOutcome(r){if(r.score===r.defense)return '동점 · 수비군 승리';if(uid===r.attacker)return r.won?'공격 승리 · 영토 점령':'공격 패배';if(uid===r.defender)return r.won?'수비 실패':'수비 성공';return r.won?'공격군 승리':'수비군 승리';}
function chatFiltersHTML(){return [['all','모두'],['talk','대화'],['system','공지']].map(([v,l])=>`<button data-chat-filter="${v}" aria-pressed="${chatFilter===v}">${l}</button>`).join('');}
function visibleChat(){return filterChat(publicChat(chatMessages(chat)),chatFilter);}
function markVisibleChat(){if(document.hidden||!uid)return;for(const el of [$('chat-preview'),$('chat-history')].filter(Boolean)){const rect=el.getBoundingClientRect();if(rect.width&&rect.height&&rect.top<innerHeight&&rect.bottom>0&&el.scrollHeight-el.scrollTop-el.clientHeight<=40){for(const row of el.querySelectorAll('[data-chat-seq]')){const r=row.getBoundingClientRect();if(r.bottom>Math.max(0,rect.top)&&r.top<Math.min(innerHeight,rect.bottom))chatSeen.add(row.dataset.chatSeq);}}}chatSeen=new Set([...chatSeen].filter(id=>publicChat(chatMessages(chat)).some(m=>String(m.seq)===id)));fieldMemory?.set('chatSeen',[...chatSeen]);}
function updateChatUnread(){markVisibleChat();const n=publicChat(chatMessages(chat)).filter(m=>!chatSeen.has(String(m.seq))).length;$('chat-unread').textContent=n||'';$('mobile-unread').textContent=n||'';}
function replaceChatList(el,messages){if(!el)return;const follow=el.scrollHeight-el.scrollTop-el.clientHeight<=40,oldTop=el.scrollTop,anchor=[...el.querySelectorAll('[data-chat-seq]')].find(r=>r.offsetTop+r.offsetHeight>=oldTop),offset=anchor?anchor.offsetTop-oldTop:0;el.innerHTML=messages.length?chatLines(messages):'<p class="chat-empty">보관된 최근 50개 중 해당 메시지가 없습니다.</p>';if(follow)el.scrollTop=el.scrollHeight;else{const next=anchor?[...el.children].find(r=>r.dataset.chatSeq===anchor.dataset.chatSeq):null;el.scrollTop=next?next.offsetTop-offset:0;if(!next&&anchor)toast('읽던 오래된 메시지가 교체됐습니다.');}if(el.id==='chat-history'){$('chat-new').hidden=follow;const n=messages.filter(m=>!chatSeen.has(String(m.seq))).length;$('chat-new').textContent=`새 메시지 ${n}개 · 아래로`;}}
function renderChat(){fieldScope();if(fieldMemory&&chat&&!fieldMemory.get('chatInitialized',false)){chatSeen=new Set(publicChat(chatMessages(chat)).map(m=>String(m.seq)));fieldMemory.set('chatSeen',[...chatSeen]);fieldMemory.set('chatInitialized',true);}const messages=visibleChat(),signature=JSON.stringify([chatFilter,messages]);if(signature!==lastChatSignature){lastChatSignature=signature;replaceChatList($('chat-preview'),messages.slice(-CHAT_PREVIEW_LIMIT));if(modalKind==='chat')replaceChatList($('chat-history'),messages);}$('chat-filters').innerHTML=chatFiltersHTML();if($('chat-modal-filters'))$('chat-modal-filters').innerHTML=chatFiltersHTML();$('chat-count').textContent=`최근 ${Math.min(CHAT_PREVIEW_LIMIT,messages.length)}개`;updateChatUnread();renderStatus();}
function showChat(){openModal(`<div class="modal-inner"><div class="modal-heading"><div><h2>전체 채팅</h2><p>보관된 최신 50개 · 필터로 골라 보세요.</p></div><button class="close-button" data-close aria-label="닫기">×</button></div><div id="chat-modal-filters" class="field-filters">${chatFiltersHTML()}</div><div class="chat-history" id="chat-history">${chatLines(visibleChat())}</div><button id="chat-new" data-chat-bottom hidden>새 메시지</button><form id="chat-modal-form" class="chat-form"><label class="sr-only" for="chat-modal-input">전체에 보낼 채팅</label><input id="chat-modal-input" maxlength="200" placeholder="전체에 보낼 메시지" value="${esc($('chat-input').value)}"><button id="chat-modal-send">보내기</button></form><p class="rules-footnote">필터는 보관된 최근 50개에만 적용됩니다.</p></div>`,'chat');$('chat-history').scrollTop=$('chat-history').scrollHeight;renderStatus();$('chat-history').addEventListener('scroll',updateChatUnread,{passive:true});updateChatUnread();if(uid)$('chat-modal-input').focus();}
function installFieldEvents(){
  document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;
    if(b.hasAttribute('data-city')){if(busy||myPendingBattle(world,uid))return;const t=world.territories[b.dataset.city];if(t?.owner!==uid){toast('도시 소유권이 바뀌었습니다.');render();return;}locateOfficer(t.id);}
    else if(b.hasAttribute('data-city-list')){sideTab='command';clearTerritory();}
    else if(b.hasAttribute('data-open-my-news'))openMyNews();
    else if(b.hasAttribute('data-battle-record'))replayBattle(b.dataset.battleRecord);
    else if(b.hasAttribute('data-news-city')){if(modalKind==='history')closeModal();locateOfficer(b.dataset.newsCity);}
    else if(b.hasAttribute('data-news-read')){readNews();toast('표시된 소식을 확인했습니다.');}
    else if(b.hasAttribute('data-news-scope')){newsFilter.scope=b.dataset.newsScope;fieldMemory?.set('newsFilter',newsFilter);lastInfoSignature='';if(modalKind==='history')showHistory();else render();}
    else if(b.hasAttribute('data-chat-filter')){chatFilter=b.dataset.chatFilter;fieldMemory?.set('chatFilter',chatFilter);lastChatSignature='';renderChat();}
    else if(b.hasAttribute('data-chat-bottom')){$('chat-history').scrollTop=$('chat-history').scrollHeight;b.hidden=true;updateChatUnread();}
    else if(b.hasAttribute('data-highlight')){map.highlight=b.dataset.highlight;map.paint();}
    else if(b.hasAttribute('data-jump')){const el=$(b.dataset.jump);if(b.dataset.jump==='command-panel'&&$('command-panel').classList.contains('is-collapsed'))$('panel-toggle').click();el.scrollIntoView({behavior:'smooth',block:'start'});}
  });
  document.addEventListener('input',event=>{const e=event.target;if(e.id==='city-query'){cityFilter.query=e.value;fieldMemory?.set('cities',cityFilter);const start=e.selectionStart;lastSideSignature='';render();const n=$('city-query');n?.focus();n?.setSelectionRange(start,start);}if(e.id==='chat-input'||e.id==='chat-modal-input'){fieldScope()?.set('draft',e.value);const other=$(e.id==='chat-input'?'chat-modal-input':'chat-input');if(other)other.value=e.value;}});
  document.addEventListener('change',event=>{const e=event.target;if(e.id==='city-filter'||e.id==='city-sort'){cityFilter[e.id==='city-filter'?'filter':'sort']=e.value;fieldMemory?.set('cities',cityFilter);lastSideSignature='';render();}if(e.hasAttribute('data-news-kind')){newsFilter.kind=e.value;fieldMemory?.set('newsFilter',newsFilter);lastInfoSignature='';if(modalKind==='history')showHistory();else render();}});
  $('fit-own').onclick=()=>map.fitOwned();$('map-info').onchange=event=>{map.info=event.target.value;map.paint();};$('retry-sync').onclick=()=>run(()=>store.retryRead());$('apply-update').onclick=applyNewVersion;
  document.addEventListener('scroll',updateChatUnread,{passive:true,capture:true});$('chat-preview').addEventListener('scroll',updateChatUnread,{passive:true});$('chat-preview').addEventListener('click',e=>{if(e.target.closest('.system-message'))showChat();});document.addEventListener('scroll',readVisibleNews,{capture:true,passive:true});
  const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting)document.querySelectorAll('[data-jump]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.jump===e.target.id)));},{threshold:.2});for(const id of ['map-card','command-panel','chat-panel'])observer.observe($(id));
  window.visualViewport?.addEventListener('resize',()=>document.body.classList.toggle('keyboard-open',visualViewport.height<innerHeight*.75));
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkNewVersion();});window.addEventListener('storage',event=>{if(event.key===fieldMemory?.key){try{const other=JSON.parse(event.newValue||'{}');fieldMemory.value.news={at:Math.max(other.news?.at||0,fieldMemory.value.news?.at||0),ids:[...new Set([...(other.news?.ids||[]),...(fieldMemory.value.news?.ids||[])])].filter(id=>world.history[id])};}catch{}fieldPanels();}});
}
async function checkNewVersion(){if(location.hostname==='localhost'||location.hostname==='127.0.0.1'||Date.now()-lastVersionCheck<300000)return;lastVersionCheck=Date.now();try{const response=await fetch(new URL('./version.json',import.meta.url),{cache:'no-store'});if(!response.ok)return;const v=await response.json();const loaded=new URL([...document.scripts].find(s=>s.src.includes('/app.js'))?.src||location.href).searchParams.get('v');$('apply-update').hidden=!loaded||!v.id||loaded===v.id;}catch{}}
function applyNewVersion(){if(busy||settling||myPendingBattle(world,uid)){toast('진행 중인 처리가 끝난 뒤 적용해 주세요.');return;}const draft=$('chat-modal-input')?.value||$('chat-input').value;if(!fieldScope()?.set('draft',draft)&&draft){toast('작성 중인 채팅을 저장할 수 없습니다. 먼저 보내거나 비워 주세요.');return;}fieldMemory?.set('restore',{source,target,ids:[...selected],view:map.viewState()});location.reload();}

let savedTheme='overview',mapSummaryCollapsed=false;try{savedTheme=localStorage.getItem('samguk-map-view')||'overview';mapSummaryCollapsed=localStorage.getItem('samguk-map-summary-collapsed')==='true';}catch{};
function setMapTheme(theme){theme=theme==='war'?'war':'overview';map.mode=theme;$('map-card').dataset.theme='board';document.querySelectorAll('[data-map-theme]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.mapTheme===theme)));try{localStorage.setItem('samguk-map-view',theme);}catch{}map.paint();renderMapSummary();}
function renderMapSummary(){if(!$('map-strategy'))return;$('map-strategy').hidden=mapSummaryCollapsed;const toggle=$('map-summary-toggle');toggle.setAttribute('aria-expanded',String(!mapSummaryCollapsed));toggle.textContent=mapSummaryCollapsed?'요약 펼치기 ▾':'요약 접기 ▴';toggle.setAttribute('aria-label',(map.mode==='war'?'전쟁 준비':'천하 판세')+' 요약 '+(mapSummaryCollapsed?'펼치기':'접기'));if(mapSummaryCollapsed)return;$('map-strategy').innerHTML=map.mode==='war'?routeHTML(view,uid,source,target,[...selected],currentTime(),chance.value?.chance!==undefined?probabilityText(chance.value.chance,chance.value.approximate):''):overviewHTML(view,uid);}
$('map-summary-toggle').onclick=()=>{mapSummaryCollapsed=!mapSummaryCollapsed;try{localStorage.setItem('samguk-map-summary-collapsed',String(mapSummaryCollapsed));}catch{}renderMapSummary();};
