$('panel-toggle').onclick=()=>{const collapsed=$('command-panel').classList.toggle('is-collapsed');$('panel-toggle').setAttribute('aria-expanded',String(!collapsed));$('panel-toggle').textContent=collapsed?'정보 펼치기':'정보 접기';};
$('modal-content').addEventListener('change',event=>{if(event.target.dataset.reviveUnit){if(event.target.checked)revival.ids.add(event.target.dataset.reviveUnit);else revival.ids.delete(event.target.dataset.reviveUnit);renderRevival();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('modal').open)clearTerritory();});
let seasonHistory=null,seasonHistoryMap=null,seasonHistoryLoading=false,seasonSwitching=false,forcedArchive=false;
let victorySeen='',seasonPollAt=0;
function syncSeasonUI(){
  const now=currentTime(),x=world.season,banner=$('season-banner');if(!x){banner.hidden=true;return;}
  document.body.classList.toggle('is-ended',!!x.endedAt);banner.hidden=false;
  const atText=at=>new Date(at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'});
  if(x.endedAt){const opening=nextSeasonAt(world,now),victory=seasonVictory(world);banner.textContent=victory.title+' · 다음 개막 '+clockText(opening-now)+' 후';banner.title=victory.title+' · 다음 시즌 '+atText(opening)+' 개막';banner.onclick=()=>showVictory();if(victorySeen!==x.id&&!busy&&modalKind!=='battle'&&modalKind!=='guard'){victorySeen=x.id;showVictory();}if(now>=opening&&store?.mode==='online'&&!seasonSwitching&&Date.now()>seasonPollAt){seasonSwitching=true;seasonPollAt=Date.now()+15000;source=null;target=null;selected.clear();closeModal();googleLogin(true).finally(()=>seasonSwitching=false);}}
  else{banner.onclick=null;banner.textContent='시즌 '+x.number+' · 72/90곳(80%) 점령 시 우승'+(x.deadline?' · 남은 '+clockText(x.deadline-now):' · 시간 제한 없음');banner.title=x.deadline?'시즌 '+x.number+' · 전체 90곳 중 72곳 점령 또는 72시간 종료 시 최다 영토 우승 · 마감 '+atText(x.deadline):banner.textContent;}
}
let aiChoiceRequest=0;
function refreshAiChoice(count){const request=++aiChoiceRequest;const panel=$('ai-choice-panel'),remote=store,seasonId=world.season?.id;if(!panel||!remote?.config?.aiServerEnabled||!remote.aiChoice)return;panel.innerHTML=aiChoiceStatusHTML();if(!remote.uid&&!uid)return;return loadAiChoice({store:remote,count,isCurrent:()=>request===aiChoiceRequest&&store===remote&&world.season?.id===seasonId&&modalKind==='victory'&&$('ai-choice-panel')===panel,render:html=>panel.innerHTML=html}).then(result=>{if(result&&count!==undefined)toast('다음 시즌 시작 군주 수를 저장했습니다.');});}
function showVictory(){const v=seasonVictory(world);if(!v)return;const x=world.season;openModal('<div class="season-victory"><p class="eyebrow">삼국지 지난 역사 · 시즌 '+x.number+'</p><h2>'+esc(v.title)+'</h2><p>'+esc(v.text)+'</p><p>'+esc(x.reason==='conquest'?'패권 기준80% 달성':'72시간 쟁패 종료')+' · 전체90영토</p><p>다음 시즌: '+new Date(nextSeasonAt(world,currentTime())).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+'</p><div id="ai-choice-panel"></div><button data-season-results>최종 지도·랭킹</button><button data-close>전장 보기</button></div>','victory');refreshAiChoice();}
async function showSeasonHistory(requested){
  if(seasonHistoryLoading)return;seasonHistoryLoading=true;const panel=$('season-history');panel.hidden=false;panel.dataset.tab='map';const heading='<header><div><h1>삼국지 지난 역사</h1><p>최종 지도와 랭킹 · 시즌 우승은 영토 기준</p></div><button id="leave-history">전장으로 돌아가기</button></header>';panel.innerHTML=heading+'<p>기록을 불러오는 중입니다.</p>';$('leave-history').onclick=()=>panel.hidden=true;
  try{if(!store?.sdk||!uid)throw Error('Google 로그인 후 지난 기록을 볼 수 있습니다.');let index=(await store.sdk.get(store.sdk.ref(store.db,'seasonIndex'))).val()||{};if(world.season?.endedAt)index[world.season.id]={title:'시즌 '+world.season.number};const ids=Object.keys(index).sort((a,b)=>Number(b.slice(7))-Number(a.slice(7)));const selectedId=requested||ids[0]||'test';let archive;if(selectedId==='test'){const raw=(await store.sdk.get(store.sdk.ref(store.db,'worlds/main'))).val();archive=archiveTestSeason(raw);}else archive=(await store.sdk.get(store.sdk.ref(store.db,'worlds/'+selectedId+'/season/result'))).val();if(!archive)throw Error('최종 기록을 아직 정리하고 있습니다.');archive.rankings=Object.values(archive.rankings||{});archive.territories=Object.values(archive.territories||{});seasonHistoryMap?.observer.disconnect();panel.innerHTML=heading+'<div class="season-tab-buttons">'+[...ids,'test'].map(id=>'<button data-history-season="'+esc(id)+'">'+esc(id==='test'?'테스트 시즌':index[id]?.title||id)+'</button>').join('')+'</div><h2>'+esc(archive.title)+'</h2><div class="season-record-layout"><div class="season-record-map map-card" id="season-record-map"><div class="map-toolbar">최종 결과 지도 <div><button data-zoom="out">−</button><button data-zoom="all" data-map-zoom>전체</button><button data-zoom="in">＋</button></div></div><div class="map-viewport"><svg aria-label="최종 결과 지도"></svg></div><p id="season-map-caption">영토를 선택하면 당시 소유자와 병력을 확인합니다.</p></div><aside class="season-record-ranking">'+archive.rankings.map(p=>'<article><strong>'+p.rank+'위 · '+esc(p.name)+'</strong><small>영토 '+p.territories+'곳 · 병력 '+p.army+'명 · 장수 '+(p.heroes??'기록 없음')+'<br>처치 '+p.kills+' · 전사 '+p.deaths+'</small></article>').join('')+'</aside></div>';
  const saved=archiveMapWorld(archive);seasonHistoryMap=new TerritoryMap($('season-record-map'),id=>{const t=saved.territories[id];$('season-map-caption').textContent=placeInfo(id).ko+' · '+(saved.players[t.owner]?.name||'중립')+' · '+t.units.length+'명';});seasonHistoryMap.setWorld(saved,null,null,null);panel.querySelectorAll('[data-history-season]').forEach(b=>b.onclick=()=>showSeasonHistory(b.dataset.historySeason));$('leave-history').onclick=()=>panel.hidden=true;
  }catch(error){panel.innerHTML=heading+'<p>'+esc(error.message)+'</p>';$('leave-history').onclick=()=>panel.hidden=true;}finally{seasonHistoryLoading=false;}
}
$('modal-content').addEventListener('click',e=>{if(e.target.closest('[data-season-results]')){closeModal();showSeasonHistory(world.season.id);}});
try{if(sessionStorage.getItem('samguk-chat-drawer')==='true'){document.body.classList.add('chat-drawer-open');$('chat-toggle').setAttribute('aria-expanded','true');}}catch{}
new ResizeObserver(entries=>document.documentElement.style.setProperty('--topbar-height',entries[0].target.getBoundingClientRect().height+'px')).observe(document.querySelector('.topbar'));
installFieldEvents();render();renderChat();checkNewVersion();setInterval(tick,1000);
if(sessionStorage.getItem('samguk-online-mode')==='practice')practiceLogin();else if(CONFIG.enabled)googleLogin(true);

$('map-strategy').addEventListener('click',e=>{const b=e.target.closest('[data-map-ruler]');if(b){map.highlight=map.highlight===b.dataset.mapRuler?'':b.dataset.mapRuler;map.paint();}});

$('modal-content').addEventListener('click',e=>{if(e.target.closest('[data-gallery-back]')){const saved=officerDetail?.gallery;if(saved){galleryTier=saved.tier;officerDetail=null;renderGallery();$('modal').scrollTop=saved.top;}}});

$('modal-content').addEventListener('click',e=>{if(e.target.closest('[data-ai-retry]'))return refreshAiChoice();const b=e.target.closest('[data-ai-count]');if(b&&store?.aiChoice)return refreshAiChoice(Number(b.dataset.aiCount));});
